export class RefundError extends Error {}

export async function refundOrder({ gateway, logger, metrics }, orderId) {
  const log = logger.child({ orderId });
  try {
    await gateway.refund(orderId);
  } catch (err) {
    log.error({ err }, "payment gateway refused refund");
    throw new RefundError("refund failed", { cause: err });
  }
  metrics.count("refunds");
  log.info({ event: "order.refunded" }, "order refunded");
}

